#!/usr/bin/env python3
"""Verify Linux CLI trust against identities generated by the real server."""

import contextlib
import http.client
import json
import os
from pathlib import Path
import re
import subprocess
import sys
import tempfile
import time
import unittest


ROOT = Path(__file__).resolve().parents[1]
SERVER = str(ROOT / "bin/entropy-server")
CLIENT = str(ROOT / "bin/entropy-client")
HOST = "127.0.0.2"  # Another loopback IPv4: no external host, DNS or proxy required.


@unittest.skipUnless(sys.platform.startswith("linux"), "tests Linux Go SSL_CERT_FILE trust")
class ClientTLSTests(unittest.TestCase):
    def setUp(self):
        temporary = tempfile.TemporaryDirectory(prefix="entropy-client-tls-")
        self.addCleanup(temporary.cleanup)
        self.directory = Path(temporary.name)
        self.empty_roots = self.directory / "empty-roots"
        self.empty_roots.mkdir()
        self.sequence = 0

    def generate(self, name, host=HOST):
        cert, key = self.directory / f"{name}.pem", self.directory / f"{name}-key.pem"
        result = subprocess.run([SERVER, "generate-cert", f"-cert-file={cert}", f"-key-file={key}",
                                 f"-hosts={host}"], capture_output=True, timeout=5, check=False)
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertFalse(result.stdout)
        self.assertNotIn(b"PRIVATE KEY", result.stderr)
        return cert, key

    @contextlib.contextmanager
    def server(self, identity, port=0):
        cert, key = identity
        self.sequence += 1
        log_path = self.directory / f"server-{self.sequence}.log"
        with log_path.open("wb") as log:
            process = subprocess.Popen([SERVER, f"-http={HOST}:0", f"-https={HOST}:{port}",
                                        "-enable-https=true", "-device=/dev/urandom", "-require-device=true",
                                        f"-cert-file={cert}", f"-key-file={key}"],
                                       stdout=subprocess.PIPE, stderr=log)
            try:
                deadline = time.monotonic() + 5
                while True:
                    text = log_path.read_bytes()
                    listeners = dict(re.findall(rb"(HTTPS?) listener\s+\[OK\] 127\.0\.0\.2:(\d+)\n", text))
                    if b"HTTP" in listeners and b"HTTPS" in listeners:
                        connection = http.client.HTTPConnection(HOST, int(listeners[b"HTTP"]), timeout=.3)
                        try:
                            connection.request("GET", "/ready")
                            response = connection.getresponse()
                            response.read(8192)
                            if response.status == 200:
                                break
                        except OSError:
                            pass
                        finally:
                            connection.close()
                    if process.poll() is not None or time.monotonic() >= deadline:
                        self.fail(f"server did not become ready: {text[-8192:]!r}")
                    time.sleep(.02)
                yield int(listeners[b"HTTPS"])
            finally:
                if process.poll() is None:
                    process.terminate()
                try:
                    stdout, _ = process.communicate(timeout=3)
                except subprocess.TimeoutExpired:
                    process.kill()
                    process.communicate()
                    self.fail("TLS fixture server did not shut down")
                self.assertEqual(process.returncode, 0, log_path.read_bytes()[-8192:])
                self.assertFalse(stdout)

    def capture(self, port, trust, success, error=b""):
        for mode, scheme, flag, path in [("pull", "https", "url", "/v1/data/random"),
                                         ("stream", "wss", "wsurl", "/stream")]:
            with self.subTest(mode=mode, trust=trust.name, success=success):
                self.sequence += 1
                output = self.directory / f"capture-{self.sequence}.bin"
                report = self.directory / f"capture-{self.sequence}.jsonl"
                env = dict(os.environ, SSL_CERT_FILE=str(trust), SSL_CERT_DIR=str(self.empty_roots))
                result = subprocess.run([CLIENT, "-headless", f"-mode={mode}",
                                         f"-{flag}={scheme}://{HOST}:{port}{path}", "-slice=65536",
                                         "-refresh=25ms", "-analysis-bytes=256", "-duration=3s",
                                         f"-output={output}", "-output-bytes=65536", f"-report={report}",
                                         "-retries=2", "-retry-delay=1ms"],
                                        env=env, capture_output=True, timeout=6, check=False)
                self.assertFalse(result.stdout, "diagnostics leaked onto raw-output stdout")
                self.assertNotIn(b"PRIVATE KEY", result.stderr)
                self.assertNotIn(b"transport retry", result.stderr)
                summary = json.loads(report.read_text().splitlines()[-1])
                self.assertEqual(summary["failed"], not success, (summary, result.stderr))
                if success:
                    self.assertEqual(result.returncode, 0, result.stderr)
                    self.assertEqual(output.stat().st_size, 65536)
                    self.assertEqual(summary["output_written_bytes"], 65536)
                    self.assertEqual(summary["termination"], "output_limit")
                else:
                    self.assertNotEqual(result.returncode, 0, result.stderr)
                    self.assertIn(error, result.stderr)
                    self.assertEqual(output.stat().st_size, 0)
                    self.assertEqual(summary["received_bytes"], 0)
                    self.assertEqual(summary["output_written_bytes"], 0)

    def test_generated_identity_and_replacement(self):
        original = self.generate("original")
        replacement = self.generate("replacement")
        overlap = self.directory / "overlap.pem"
        overlap.write_bytes(original[0].read_bytes() + replacement[0].read_bytes())
        with self.server(original) as port:
            self.capture(port, original[0], True)
            self.capture(port, replacement[0], False, b"unknown authority")
        # Restart the same endpoint with a new key and certificate. Each capture
        # starts a fresh CLI process so changes to its Linux trust file are read.
        with self.server(replacement, port) as restarted_port:
            self.assertEqual(restarted_port, port)
            self.capture(port, original[0], False, b"unknown authority")
            self.capture(port, overlap, True)
            self.capture(port, replacement[0], True)

    def test_trusted_identity_still_requires_matching_ipv4_san(self):
        wrong_host = self.generate("wrong-host", "127.0.0.1")
        with self.server(wrong_host) as port:
            self.capture(port, wrong_host[0], False, b"not 127.0.0.2")


if __name__ == "__main__":
    unittest.main()
